package fleetflow.engine.string;
public final class RabinKarp { private RabinKarp(){} public static boolean contains(String text,String pattern){if(text==null||pattern==null||pattern.length()>text.length())return false;if(pattern.isEmpty())return true;int m=pattern.length();long target=0,window=0,power=1,base=257;for(int i=0;i<m;i++){target=target*base+pattern.charAt(i);window=window*base+text.charAt(i);if(i<m-1)power*=base;}for(int i=0;i<=text.length()-m;i++){if(target==window&&text.regionMatches(i,pattern,0,m))return true;if(i<text.length()-m)window=(window-text.charAt(i)*power)*base+text.charAt(i+m);}return false;} }
